$ErrorActionPreference='Stop'
$taskRoot=(Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
$taskEntries=@(foreach($taskMode in @('thermal','cryo','vacuum','pressure')){
 [ordered]@{id=('device.effect.'+$taskMode);mode=$taskMode;action='keep';owner='R3 008';consumer=('Scripts/World/'+@{thermal='thermal_blast_effects.gd';cryo='cryo_beam_effects.gd';vacuum='vacuum_burst_effects.gd';pressure='pressure_vice_effects.gd'}[$taskMode]);dependencies=@('R3 007 shared player/sockets','R2 production assets','phase_device_target eligibility');art=('assets/effects/'+$taskMode+'/v1/sprite_frames.tres');atlas=('assets/effects/'+$taskMode+'/v1/atlas.png');source_manifest=('assets/effects/'+$taskMode+'/v1/manifest.json');phase_mapping=[ordered]@{start='start';loop='stream';impact='impact';stop='release'};audio=[ordered]@{start=('assets/audio/Device/'+$taskMode+'_start.wav');loop=('assets/audio/Device/'+$taskMode+'_loop.wav');stop=('assets/audio/Device/'+$taskMode+'_release.wav');impact='qualified loop/contact presentation; no missing separate impact audio event'};source_project=$(if($taskMode -in @('thermal','cryo')){'tools/art/'+$taskMode+'_v1/generation.md'}else{'tools/art/chamber_v1/generation.md'});cell_px=@(128,128);conversion='Existing presenter draw sizes in world units; no global raster rescale. Actor/camera unchanged.';normal_states=@('start','sustain miss','sustain qualified impact','release','idle');reduced='Existing narrower stream/local contact retained; auxiliary motes removed; chamber one ring instead of two';locked='Existing normal mode/capability gates + target cue; no emission/unlock from fixture art';bounds=[ordered]@{range_world=100;max_stream_tiles=8;max_particle_slots=18;max_voices=1;max_local_ring_radius_world=$(if($taskMode -in @('pressure','vacuum')){23}else{0});shimmer_patches=$(if($taskMode -eq 'thermal'){2}else{0})};review='Isolated current presenter/shared-rig/new-biome review; human listening/Android pending';retirement_eligible=$false}
})
$taskFiles=@(Get-ChildItem (Join-Path $taskRoot 'assets/devices/phase_device/v1') -File|Where-Object {$_.Extension -ne '.import'})
foreach($taskMode in @('thermal','cryo','vacuum','pressure','chamber')){$taskFiles+=@(Get-ChildItem (Join-Path $taskRoot ('assets/effects/'+$taskMode+'/v1')) -File|Where-Object {$_.Extension -ne '.import'})}
$taskFiles+=@(Get-ChildItem (Join-Path $taskRoot 'assets/audio/Device') -Filter '*.wav'|Where-Object {$_.Name -match '^(thermal|cryo|vacuum|pressure)_(start|loop|release)\.wav$'})
$taskRecords=@(foreach($taskFile in $taskFiles){[ordered]@{path=[IO.Path]::GetRelativePath($taskRoot,$taskFile.FullName).Replace('\','/');sha256=(Get-FileHash -LiteralPath $taskFile.FullName -Algorithm SHA256).Hash;bytes=$taskFile.Length;action='keep'}})
$taskAudioImports=@(foreach($taskFile in $taskFiles|Where-Object {$_.Extension -eq '.wav'}){[ordered]@{path=([IO.Path]::GetRelativePath($taskRoot,$taskFile.FullName).Replace('\','/')+'.import');sha256=(Get-FileHash -LiteralPath ($taskFile.FullName+'.import') -Algorithm SHA256).Hash;compression_mode=0;meaning='Original PCM import, no recompression; independent review retains same params'}})
[ordered]@{schema_version=1;owner='R3 008';status='Compatibility reviewed; external acceptance pending';mode_count=4;scope='Reuse/compatibility metadata only; existing presenters/campaign remain authoritative and unchanged';entries=$taskEntries;handheld='assets/devices/phase_device/v1/sprite_frames.tres';socket_authority='Native Texture metadata and actual shared phase_device_rig; old sockets.json attachment_integration note is historical R2 003';cryo_sample='assets/effects/cryo/v1/sample_frames.tres';chamber_sample='assets/effects/chamber/v1/sprite_frames.tres';cue='Scripts/World/phase_device_target_cue.gd';files=$taskRecords;audio_imports=$taskAudioImports;gaps='No missing production phase/VFX/audio family found; no art/audio regeneration or source replacement justified';stage_limits='R3 007 user/Android and wider R3 002 art acceptance still pending'}|ConvertTo-Json -Depth 12|Set-Content (Join-Path $taskRoot 'assets/devices/phase_device/r3_compatibility/catalog.json') -Encoding utf8
